import React, { useState } from 'react';
import { BrowserRouter, Routes, Route } from 'react-router-dom';
import { Sidebar, 
FeatureItem } from '@components/Sidebar';
import Navbar from '@components/Navbar';

const features: FeatureItem[] = [
  { id: 'dashboard', label: 'Dashboard', path: '/dashboard', icon: '⊞' },
  { id: 'users',     label: 'Users',     path: '/users',     icon: '👥' },
];

export default function App() {
  const [collapsed, setCollapsed] = useState(false);
  const sidebarWidth = collapsed ? 56 : 280;

  // Convert FeatureItem → NavItem shape Navbar expects
  const navItems = features
    .filter(f => f.path)
    .map(f => ({ id: f.id, label: f.label, path: f.path! }));

  return (
    <BrowserRouter>
      <Sidebar
        features={features}
        collapsed={collapsed}
        onToggle={() => setCollapsed(c => !c)}
      />
      <Navbar
        sidebarWidth={sidebarWidth}
        navItems={navItems}           
      />
      <main style={{ marginLeft: sidebarWidth, marginTop: 64, padding: 24, transition: 'margin-left 0.25s ease' }}>
        <Routes>
          <Route path="/dashboard" element={<div>Dashboard Page</div>} />
          <Route path="/users"     element={<div>Users Page</div>} />
        </Routes>
      </main>
    </BrowserRouter>
  );
}
